def parse_invoice_number(invoice_number: str) -> Optional[Tuple[str, int]]:
    """
    Split an invoice number into (prefix, number); return None when it does not follow the
    ``<prefix>-<number>`` format produced by ``generate_invoice_number``.
    """
    prefix, separator, number = invoice_number.rpartition('-')
    if not separator or not number.isdigit():
        return None
    return prefix, int(number)


